cat > /opt/opa-workshop/q7/adapter.py <<'PY'
import json
import sys

event = json.load(sys.stdin)
allowed = False
if 'error' in event:
    reason = 'timeout' if event['error'] == 'timeout' else 'error'
elif event.get('status') != 200:
    reason = 'error'
elif not isinstance(event.get('body'), dict):
    reason = 'invalid'
elif 'result' not in event['body']:
    reason = 'undefined'
elif event['body']['result'] is True:
    allowed, reason = True, 'allow'
elif event['body']['result'] is False:
    reason = 'deny'
else:
    reason = 'invalid'
print(json.dumps({'allow': allowed, 'reason': reason}))
PY
